const app=document.querySelector("#app"),count=document.querySelector("#count"),tpl=document.querySelector("#product-template");let cart=JSON.parse(localStorage.getItem("novastore-cart")||"[]");const money=n=>new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:0}).format(n);function save(){localStorage.setItem("novastore-cart",JSON.stringify(cart));count.textContent=cart.reduce((s,i)=>s+i.qty,0)}async function getProducts(search="",category="all"){const q=new URLSearchParams({search,category}),r=await fetch(`/api/products?${q}`);if(!r.ok)throw Error("Could not load products.");return r.json()}function card(p){const f=tpl.content.cloneNode(true);f.querySelector(".visual").textContent=p.icon;f.querySelector(".category").textContent=p.category;f.querySelector(".name").textContent=p.name;f.querySelector(".description").textContent=p.description;f.querySelector(".price").textContent=money(p.price);f.querySelector(".rating").textContent=`★ ${p.rating}`;f.querySelector(".add").onclick=()=>{const e=cart.find(i=>i.id===p.id);e?e.qty++:cart.push({...p,qty:1});save();alert(`${p.name} added to cart.`)};return f}async function shop(){app.innerHTML=`<section class="page"><div class="hero"><p>Full-Stack Capstone</p><h1>Modern tech, simple shopping.</h1><p>Products are fetched from a Node/Express REST API.</p></div><div class="controls"><input id="search" placeholder="Search products…"><select id="category"><option value="all">All categories</option><option>Audio</option><option>Accessories</option><option>Wearables</option><option>Workspace</option></select></div><p id="status">Loading…</p><div id="grid" class="grid"></div></section>`;const search=app.querySelector("#search"),category=app.querySelector("#category"),grid=app.querySelector("#grid"),status=app.querySelector("#status");async function load(){try{const d=await getProducts(search.value.trim(),category.value);grid.innerHTML="";d.products.forEach(p=>grid.append(card(p)));status.textContent=`${d.count} products found.`}catch(e){status.textContent=e.message}}let t;search.oninput=()=>{clearTimeout(t);t=setTimeout(load,250)};category.onchange=load;load()}function about(){app.innerHTML=`<section class="page"><div class="hero"><p>Project Architecture</p><h1>Small full-stack architecture.</h1><p>Express serves the site and exposes JSON APIs. The frontend uses client-side hash routing.</p></div><div class="card"><h2>Architecture</h2><p><b>Backend:</b> Node.js + Express</p><p><b>API:</b> /api/products</p><p><b>Routing:</b> #/, #/about, #/cart</p><p><b>Persistence:</b> localStorage cart</p></div></section>`}function cartPage(){const total=cart.reduce((s,i)=>s+i.price*i.qty,0);app.innerHTML=`<section class="page"><div class="hero"><p>Shopping Cart</p><h1>Your cart.</h1><p>Cart data stays after browser refresh using localStorage.</p></div><div id="cart-list" class="cart-list"></div><div class="card"><b>Total: ${money(total)}</b></div></section>`;const list=app.querySelector("#cart-list");if(!cart.length){list.innerHTML='<div class="card">Your cart is empty.</div>';return}cart.forEach(i=>{const r=document.createElement("div");r.className="cart-row";r.innerHTML=`<div><b>${i.icon} ${i.name}</b><p>${i.qty} × ${money(i.price)}</p></div><button>Remove</button>`;r.querySelector("button").onclick=()=>{cart=cart.filter(x=>x.id!==i.id);save();cartPage()};list.append(r)})}function route(){const r=location.hash||"#/";r==="#/about"?about():r==="#/cart"?cartPage():shop();app.focus()}window.addEventListener("hashchange",route);save();route();
